// Nav.js
import React from 'react';
import "./nav.css"
import hatLogo from "../../img/hatLogo.png";
import breakfast from "../breakfast/breakfast";

const Nav = () => {
    return (
        <div className="nav">
            <ul className="nav-list">
                <li className="nav-item"><a href="../breakfast/breakfast.js">BREAKFAST</a></li>
                <li className="nav-item"><a href="../lunch/lunch.js">LUNCH</a></li>
                <li className="nav-item logo">
                    <a href="/">
                        <img src={hatLogo} alt="Logo" className="site-logo" />
                    </a>
                </li>
                <li className="nav-item"><a href="../dinner/dinner.js">DINNER</a></li>
                <li className="nav-item"><a href="../snack/snack.js">SNACK/BAKING</a></li>
            </ul>
        </div>
    );
};

export default Nav;
